sys_script_include.script:
var LeaveBalanceAjax = Class.create();
LeaveBalanceAjax.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {
	getLeaveBalance: function() {
        var userId = this.getParameter('sysparm_user');
        var leaveType = this.getParameter('sysparm_leave_type');

        // Map the choice value to the exact column name in your table
        var columnMap = {
            'sick': 'sick_balance',
            'casual': 'casual_balance',
            'annual': 'annual_balance',
            'emergency': 'emergency_balance',
            'maternity': 'maternity_balance',
            'paternity': 'paternity_balance'
        };

        var targetColumn = columnMap[leaveType];
        if (!targetColumn) {
            return "0"; // Return 0 if the mapping is invalid
        }

        var balance = "0";
        var gr = new GlideRecord('x_2250616_leave_0_employee_leave_balance');
        gr.addQuery('employee', userId);
        gr.query();

        if (gr.next()) {
            // Dynamically get the value of the mapped column
            balance = gr.getValue(targetColumn) || "0"; 
        }

        return balance;
    },


    type: 'LeaveBalanceAjax'
});
